  useEffect(() => { inputRef.current?.focus(); }, []);

  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-b from-stone-50 to-stone-100 px-4">
      <div className="flex justify-end p-4">
        <LanguageSwitcher />
      </div>
