export const SiteView: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();

  const resolvedSlug = React.useMemo(() => {
    if (slug) return slug;
    const host = window.location.hostname.toLowerCase();
    if (!host.endsWith('dayof.love')) return null;
    const parts = host.split('.');
    if (parts.length < 3) return null; // dayof.love
    const sub = parts[0];
    if (!sub || sub === 'www') return null;
    return sub;
  }, [slug]);
  const [searchParams] = useSearchParams();
  const { i18n } = useTranslation();
  const [weddingData, setWeddingData] = useState<WeddingDataV1 | null>(null);
  const [builderSections, setBuilderSections] = useState<BuilderSectionInstance[] | null>(null);
  const [layoutConfig, setLayoutConfig] = useState<LayoutConfigV1 | null>(null);
  const [weddingSiteId, setWeddingSiteId] = useState<string | null>(null);
  const [useNewRenderer, setUseNewRenderer] = useState(false);
  const [isComingSoon, setIsComingSoon] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [privacyGate, setPrivacyGate] = useState<PrivacyGateState>('loading');
  const [hideFromSearch, setHideFromSearch] = useState(false);
  const [passwordGateError, setPasswordGateError] = useState<string | null>(null);
  const [passwordGateChecking, setPasswordGateChecking] = useState(false);

  const STORAGE_KEY = `dayof_pw_unlocked_${resolvedSlug ?? 'unknown'}`;

  const handlePasswordSubmit = async (pw: string) => {
    setPasswordGateChecking(true);
    setPasswordGateError(null);
    try {
      const { data } = await supabase.rpc('check_site_password', {
        p_slug: resolvedSlug,
        p_password: pw,
      });
      if (data === true) {
        sessionStorage.setItem(STORAGE_KEY, '1');
        setPrivacyGate('unlocked');
      } else {
        setPasswordGateError('Incorrect password. Please try again.');
      }
    } catch {
      setPasswordGateError('Could not verify password. Please try again.');
    } finally {
      setPasswordGateChecking(false);
    }
  };

  useEffect(() => {
    const loadSite = async () => {
      if (!resolvedSlug) {
        setError('Invalid site URL');
        setLoading(false);
        return;
      }

      try {
        let { data, error: fetchError } = await supabase
          .from('wedding_sites')
          .select('*')
          .eq('site_slug', resolvedSlug)
          .maybeSingle();

        // Fallback for legacy/incomplete rows where site_slug is missing but site_url exists.
        if (!data && !fetchError) {
          const byUrl = await supabase
            .from('wedding_sites')
            .select('*')
            .eq('site_url', `${resolvedSlug}.dayof.love`)
            .maybeSingle();
          data = byUrl.data;
          fetchError = byUrl.error;
        }

        if (fetchError) throw fetchError;

        if (!data) {
          setError('Wedding site not found');
          setLoading(false);
          return;
        }

        setWeddingSiteId(data.id as string);

        const siteLang = (data.default_language as string) ?? 'en';
        const userPref = localStorage.getItem('dayof_language');
        if (!userPref && (siteLang === 'en' || siteLang === 'es')) {
          i18n.changeLanguage(siteLang);
        }

        const row = data as Record<string, unknown>;
        const siteJsonMeta = (row.site_json && typeof row.site_json === 'object')
          ? (row.site_json as Record<string, unknown>)
          : null;

        const isPublished = Boolean(
          row.is_published === true ||
          siteJsonMeta?.publishStatus === 'published' ||
          (typeof siteJsonMeta?.publishedVersion === 'number' && (siteJsonMeta.publishedVersion as number) > 0) ||
          (typeof siteJsonMeta?.lastPublishedAt === 'string' && (siteJsonMeta.lastPublishedAt as string).length > 0)
        );

        if (!isPublished) {
          setIsComingSoon(true);
          setLoading(false);
          return;
        }

        const privacyMode = (data.privacy_mode as string) ?? 'public';
        const pwHash = (data.site_password_hash as string | null) ?? null;
        const hideSearch = !!(data.hide_from_search);
        const guestToken = (data.guest_access_token as string | null) ?? null;

        setHideFromSearch(hideSearch);

        if (privacyMode === 'password_protected' && pwHash) {
          const alreadyUnlocked = sessionStorage.getItem(`dayof_pw_unlocked_${resolvedSlug}`) === '1';
          if (!alreadyUnlocked) {
            setPrivacyGate('password_required');
            setLoading(false);
            return;
          }
        } else if (privacyMode === 'invite_only') {
          const urlToken = searchParams.get('token');
          const storedToken = sessionStorage.getItem(`dayof_invite_token_${resolvedSlug}`);
          const tokenToCheck = urlToken ?? storedToken;
          if (!tokenToCheck || (guestToken && tokenToCheck !== guestToken)) {
            setPrivacyGate('invite_only');
            setLoading(false);
            return;
          }
          if (urlToken) {
            sessionStorage.setItem(`dayof_invite_token_${resolvedSlug}`, urlToken);
          }
        }

        setPrivacyGate('open');

        const siteJson = safeJsonParse<BuilderProject | null>(
          data.published_json ?? data.site_json,
          null
        );

        const persistedSections = await siteRepository.fetchPublishedSections(data.id as string).catch(() => []);

        if (persistedSections.length > 0) {
          setUseNewRenderer(true);
          setBuilderSections(null);
          setLayoutConfig(null);
          setWeddingData(null);
          setWeddingSiteId(data.id as string);
          return;
        }

        if (siteJson && siteJson.pages?.length > 0) {
          const homePage = siteJson.pages.find(p => p.id === 'home') ?? siteJson.pages[0];
          const sections = homePage.sections.filter(s => s.enabled);
          const wData = safeJsonParse<WeddingDataV1>(data.wedding_data, createEmptyWeddingData());

          if (siteJson.themeTokens) {
            applyThemeTokens(siteJson.themeTokens);
          } else if (siteJson.themeId) {
            applyThemePreset(siteJson.themeId);
          } else if (wData.theme?.preset) {
            applyThemePreset(wData.theme.preset);
          }

          setBuilderSections(sections);
          setWeddingData(wData);
        } else {
          const wData = safeJsonParse<WeddingDataV1 | null>(data.wedding_data, null);
          const lConfig = safeJsonParse<LayoutConfigV1 | null>(data.layout_config, null);

          if (!wData || !lConfig) {
            setError('This wedding site is still being set up. Check back soon!');
            setLoading(false);
            return;
          }

          if (wData.theme?.preset) {
            applyThemePreset(wData.theme.preset);
          }

          setWeddingData(wData);
          setLayoutConfig(lConfig);
        }
      } catch {
        setError('Failed to load wedding site');
      } finally {
        setLoading(false);
      }
    };

    loadSite();

    return () => {
      const el = document.documentElement;
      const resetProps = [
        '--color-primary', '--color-primary-hover', '--color-primary-light',
        '--color-accent', '--color-accent-hover', '--color-accent-light',
        '--color-secondary', '--color-background', '--color-surface',
        '--color-surface-subtle', '--color-border',
        '--color-text-primary', '--color-text-secondary',
      ];
      resetProps.forEach(p => el.style.removeProperty(p));
    };
  }, [resolvedSlug, searchParams]);

  useEffect(() => {
    if (!hideFromSearch) return;
    const meta = document.createElement('meta');
    meta.name = 'robots';
    meta.content = 'noindex, nofollow';
    meta.id = 'dayof-noindex';
    document.head.appendChild(meta);
    return () => { document.getElementById('dayof-noindex')?.remove(); };
  }, [hideFromSearch]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-text-secondary">Loading wedding site...</p>
        </div>
      </div>
    );
  }

  if (isComingSoon) {
    return (
      <ComingSoonScreen />
    );
  }

  if (privacyGate === 'password_required') {
    return (
      <PasswordGate
        onSubmit={handlePasswordSubmit}
        error={passwordGateError}
        checking={passwordGateChecking}
      />
    );
  }

  if (privacyGate === 'invite_only') {
    return <InviteOnlyGate />;
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background px-4">
        <div className="max-w-md w-full bg-surface border border-border rounded-lg p-8 text-center">
          <AlertCircle className="w-16 h-16 text-error mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-text-primary mb-2">Oops!</h1>
          <p className="text-text-secondary">{error}</p>
        </div>
      </div>
    );
  }

  if (useNewRenderer && weddingSiteId) {
    return (
      <SiteViewContext.Provider value={{ weddingSiteId }}>
        <PageRendererFromDB siteId={weddingSiteId} siteSlug={resolvedSlug ?? ''} />
      </SiteViewContext.Provider>
    );
  }

  if (builderSections && weddingData) {
    return (
      <SiteViewContext.Provider value={{ weddingSiteId }}>
        <div className="builder-themed-canvas min-h-screen bg-background">
          {builderSections.map(section => (
            <SectionRenderer key={section.id} section={section} weddingData={weddingData} isPreview />
          ))}
        </div>
      </SiteViewContext.Provider>
    );
  }

  if (!weddingData || !layoutConfig) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background px-4">
        <div className="max-w-md w-full bg-surface border border-border rounded-lg p-8 text-center">
          <p className="text-text-secondary">No wedding site data found</p>
        </div>
      </div>
    );
  }

  const homePage = layoutConfig.pages.find(p => p.id === 'home') || layoutConfig.pages[0];
  if (!homePage) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background px-4">
        <div className="max-w-md w-full bg-surface border border-border rounded-lg p-8 text-center">
          <p className="text-text-secondary">No page configuration found</p>
        </div>
      </div>
    );
  }

  const enabledSections = homePage.sections.filter(section => section.enabled);

  return (
    <SiteViewContext.Provider value={{ weddingSiteId }}>
      <div className="min-h-screen bg-background">
        {enabledSections.map((sectionInstance) => {
          try {
            const SectionComponent = getSectionComponent(
              sectionInstance.type,
              sectionInstance.variant
            );
            return (
              <SectionComponent
                key={sectionInstance.id}
                data={weddingData}
                instance={sectionInstance}
              />
            );
          } catch {
            return (
              <div key={sectionInstance.id} className="py-8 px-4 bg-error-light text-error text-center">
                <p>Error rendering {sectionInstance.type} section</p>
              </div>
            );
          }
        })}
      </div>
    </SiteViewContext.Provider>
  );
};

import React, { useReducer, useMemo, useEffect, useCallback, useRef, useState } from 'react';
import { BuilderContext, initialBuilderState } from '../state/builderStore';
import { builderReducer } from '../state/builderReducer';
import { builderActions } from '../state/builderActions';
import { selectActivePage, selectSelectedSection } from '../state/builderSelectors';
import { BuilderTopBar } from './BuilderTopBar';
import { BuilderSidebarLibrary } from './BuilderSidebarLibrary';
import { BuilderCanvas } from './BuilderCanvas';
import { BuilderInspectorPanel } from './BuilderInspectorPanel';
import { TemplateGalleryPanel } from './TemplateGalleryPanel';
import { MediaLibraryPanel } from './MediaLibraryPanel';
import { ThemePalettePanel } from './ThemePalettePanel';
import { BuilderProject } from '../../types/builder/project';
import { WeddingDataV1 } from '../../types/weddingData';
import { BUILDER_AUTOSAVE_INTERVAL_MS } from '../constants/builderCapabilities';
import { mediaService } from '../services/mediaService';
import { applyThemePreset, applyThemeTokens } from '../../lib/themePresets';
import { getPublishIssue, getPublishValidationError } from '../utils/publishReadiness';
import { shouldAutoPublishFromSearch } from '../utils/publishUiHints';
import { getPublishNowAction } from '../utils/publishNowFlow';

interface BuilderShellProps {
  initialProject: BuilderProject;
  initialWeddingData?: WeddingDataV1;
  projectName?: string;
  isDemoMode?: boolean;
  onSave?: (project: BuilderProject, weddingData?: WeddingDataV1 | null) => Promise<void>;
  onPublish?: (projectId: string) => Promise<{ version: number; publishedAt: string }>;
}

export const BuilderShell: React.FC<BuilderShellProps> = ({
  initialProject,
  initialWeddingData,
  projectName,
  isDemoMode = false,
  onSave,
  onPublish,
}) => {
  const [state, dispatch] = useReducer(builderReducer, {
    ...initialBuilderState,
    weddingData: initialWeddingData ?? null,
  });

  useEffect(() => {
    dispatch({ type: 'LOAD_PROJECT', payload: initialProject });
    if (initialProject.themeTokens) {
      applyThemeTokens(initialProject.themeTokens);
    } else {
      applyThemePreset(initialProject.themeId ?? 'romantic');
    }
  // intentionally fires once on mount — LOAD_PROJECT is idempotent and sets baseline history
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const themeId = state.project?.themeId;
    const tokens = state.project?.themeTokens;
    if (!themeId) return;
    if (tokens) {
      applyThemeTokens(tokens);
    } else if (themeId !== 'custom') {
      applyThemePreset(themeId);
    }
  }, [state.project?.themeId, state.project?.themeTokens]);

  const activePage = useMemo(() => selectActivePage(state), [state]);
  const selectedSection = useMemo(() => selectSelectedSection(state), [state]);

  const contextValue = useMemo(
    () => ({ state, dispatch, activePage, selectedSection }),
    [state, dispatch, activePage, selectedSection]
  );

  const [saveError, setSaveError] = useState<string | null>(null);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [publishNotice, setPublishNotice] = useState<string | null>(null);

  const stateRef = useRef(state);
  stateRef.current = state;
  const shouldAutoPublishRef = useRef(shouldAutoPublishFromSearch(window.location.search));

  useEffect(() => {
    const weddingId = initialProject.weddingId;
    if (!weddingId || isDemoMode) {
      dispatch(builderActions.setMediaAssets([]));
      return;
    }
    mediaService.listAssets(weddingId)
      .then(assets => { dispatch(builderActions.setMediaAssets(assets)); })
      .catch((err) => {
        const message =
          err instanceof Error
            ? err.message
            : typeof (err as { message?: unknown })?.message === 'string'
              ? ((err as { message: string }).message)
              : '';

        // Gracefully degrade when media table is not present in older envs.
        if (message.includes('builder_media_assets') || message.includes('relation') || message.includes('404')) {
          dispatch(builderActions.setMediaAssets([]));
          return;
        }
        dispatch(builderActions.setError('Could not load media library. Your uploads may not appear.'));
      });
  }, [initialProject.weddingId, isDemoMode]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('openTemplates') === '1') {
      dispatch(builderActions.openTemplateGallery());
    }
  }, []);

  const handleSave = useCallback(async (): Promise<boolean> => {
    const currentState = stateRef.current;
    if (!currentState.project || !onSave) return true;
    setSaveError(null);
    dispatch({ type: 'SET_SAVING', payload: true });
    try {
      await onSave(currentState.project, currentState.weddingData);
      dispatch(builderActions.markSaved(new Date().toISOString()));
      return true;
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to save';
      setSaveError(msg);
      dispatch({ type: 'SET_SAVING', payload: false });
      return false;
    }
  }, [onSave]);

  const handleFixPublishBlockers = useCallback(() => {
    const project = stateRef.current.project;
    if (!project) return;
    const issue = getPublishIssue(project);
    if (!issue) return;

    dispatch(builderActions.setMode('edit'));

    if (issue.kind === 'no-pages') {
      dispatch(builderActions.openTemplateGallery());
      setPublishNotice('Opened Templates so you can add content before publishing.');
      setPublishError(`${issue.message} Choose a starter template or add a page first.`);
      return;
    }

    if (issue.kind === 'no-enabled-sections') {
      if (issue.firstPageId) dispatch(builderActions.setActivePage(issue.firstPageId));
      if (issue.firstSectionId) {
        dispatch(builderActions.selectSection(issue.firstSectionId));
        requestAnimationFrame(() => {
          const el = document.querySelector(`[data-section-id="${issue.firstSectionId}"]`);
          if (el) (el as HTMLElement).scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
      }
      setPublishNotice('Selected the first section. Enable it in inspector, then publish again.');
      setPublishError(`${issue.message} Select a section and toggle it on in the inspector.`);
    }
  }, []);

  const handlePublish = useCallback(async () => {
    const currentState = stateRef.current;
    if (!currentState.project || !onPublish) return;
    if (currentState.isSaving || currentState.isPublishing) return;
    setPublishError(null);
    setPublishNotice(null);

    const publishValidationError = getPublishValidationError(currentState.project);
    if (publishValidationError) {
      setPublishError(publishValidationError);
      return;
    }
    if (currentState.isDirty) {
      const saved = await handleSave();
      if (!saved) {
        setPublishError('Please resolve save errors before publishing.');
        return;
      }
    }
    dispatch({ type: 'SET_PUBLISHING', payload: true });
    try {
      const publishMeta = await onPublish(currentState.project.id);
      dispatch(
        builderActions.markPublished(
          publishMeta.version,
          publishMeta.publishedAt
        )
      );
      setPublishNotice(`Published v${publishMeta.version} successfully`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to publish';
      setPublishError(msg);
      dispatch({ type: 'SET_PUBLISHING', payload: false });
    }
  }, [onPublish, handleSave]);

  useEffect(() => {
    if (!shouldAutoPublishRef.current) return;
    if (!state.project) return;

    shouldAutoPublishRef.current = false;
    const params = new URLSearchParams(window.location.search);
    params.delete('publishNow');
    const next = `${window.location.pathname}${params.toString() ? `?${params.toString()}` : ''}${window.location.hash}`;
    window.history.replaceState({}, '', next);

    window.setTimeout(() => {
      const action = getPublishNowAction(true, state.project);
      if (action === 'fix-blockers') {
        handleFixPublishBlockers();
        return;
      }
      if (action === 'publish') {
        handlePublish();
      }
    }, 0);
  }, [state.project, handleFixPublishBlockers, handlePublish]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const meta = e.metaKey || e.ctrlKey;
      const target = e.target as HTMLElement | null;
      const isTyping = !!target && (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.tagName === 'SELECT' ||
        target.isContentEditable
      );

      if (meta && e.key === 's' && !isTyping) {
        e.preventDefault();
        handleSave();
      }
      if (meta && e.key === 'p' && !e.shiftKey && !isTyping) {
        e.preventDefault();
        dispatch(builderActions.setMode(stateRef.current.mode === 'preview' ? 'edit' : 'preview'));
      }
      if (meta && e.shiftKey && e.key.toLowerCase() === 'p' && !isTyping) {
        e.preventDefault();
        handlePublish();
      }
      if (meta && e.key === 'z' && !e.shiftKey && !isTyping) {
        e.preventDefault();
        dispatch(builderActions.undo());
      }
      if (meta && (e.key === 'y' || (e.key === 'z' && e.shiftKey)) && !isTyping) {
        e.preventDefault();
        dispatch(builderActions.redo());
      }
      if (e.key === 'Escape' && !isTyping) {
        dispatch(builderActions.selectSection(null));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSave, handlePublish]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (stateRef.current.isDirty && !stateRef.current.isSaving && onSave) {
        handleSave();
      }
    }, BUILDER_AUTOSAVE_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [handleSave, onSave]);

  useEffect(() => {
    if (!publishNotice) return;
    const timeout = window.setTimeout(() => setPublishNotice(null), 3500);
    return () => window.clearTimeout(timeout);
  }, [publishNotice]);

  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (stateRef.current.isDirty) {
        e.preventDefault();
        e.returnValue = '';
      }
    };
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, []);

  return (
    <BuilderContext.Provider value={contextValue}>
      <div className="h-screen flex flex-col bg-gray-50 overflow-hidden">
        <BuilderTopBar
          onSave={handleSave}
          onPublish={handlePublish}
          onFixPublishBlockers={handleFixPublishBlockers}
          projectName={projectName}
          saveError={saveError}
          publishError={publishError}
          publishValidationError={state.project ? getPublishValidationError(state.project) : null}
        />

        <div className="flex-1 min-h-0 flex flex-col lg:flex-row overflow-hidden">
          {state.mode === 'edit' && (
            <div className="hidden lg:block h-full min-h-0">
              <BuilderSidebarLibrary activePageId={state.activePageId} />
            </div>
          )}

          <BuilderCanvas />

          {state.mode === 'edit' && (
            <div className="hidden lg:block h-full min-h-0">
              <BuilderInspectorPanel />
            </div>
          )}
        </div>

        {publishNotice && (
          <div className="fixed bottom-4 left-4 bg-green-600 text-white px-4 py-3 rounded-xl shadow-lg text-sm flex items-center gap-2 z-50 max-w-sm">
            <span className="flex-1">{publishNotice}</span>
            <button
              onClick={() => setPublishNotice(null)}
              className="ml-2 font-bold text-lg leading-none opacity-80 hover:opacity-100"
              aria-label="Dismiss publish notice"
            >
              ×
            </button>
          </div>
        )}

        {state.error && (
          <div className="fixed bottom-4 right-4 bg-error text-text-inverse px-4 py-3 rounded-xl shadow-lg text-sm flex items-center gap-2 z-50 max-w-sm">
            <span className="flex-1">{state.error}</span>
            <button
              onClick={() => dispatch(builderActions.setError(null))}
              className="ml-2 font-bold text-lg leading-none opacity-80 hover:opacity-100"
              aria-label="Dismiss error"
            >
              ×
            </button>
          </div>
        )}

        <TemplateGalleryPanel onSaveRequest={handleSave} />
        <MediaLibraryPanel />
        <ThemePalettePanel
          isOpen={state.themePanelOpen}
          onClose={() => dispatch(builderActions.closeThemePanel())}
        />
      </div>
    </BuilderContext.Provider>
  );
};

