import type { BuilderProject } from '../../types/builder/project';

export type PublishIssue =
  | { kind: 'no-pages'; message: string }
  | { kind: 'no-enabled-sections'; message: string; firstSectionId?: string; firstPageId?: string };

export const getPublishIssue = (project: BuilderProject): PublishIssue | null => {
  if (!project.pages.length) {
    return { kind: 'no-pages', message: 'Add at least one page before publishing.' };
  }

  const firstSection = project.pages.flatMap((p) => p.sections.map((s) => ({ pageId: p.id, sectionId: s.id })))[0];
  const hasEnabledSection = project.pages.some((page) => page.sections.some((section) => section.enabled));
  if (!hasEnabledSection) {
    return {
      kind: 'no-enabled-sections',
      message: 'Enable at least one section before publishing.',
      firstSectionId: firstSection?.sectionId,
      firstPageId: firstSection?.pageId,
    };
  }

  return null;
};

export const getPublishValidationError = (project: BuilderProject): string | null =>
  getPublishIssue(project)?.message ?? null;

import { BuilderProject } from '../../types/builder/project';
import { WeddingDataV1 } from '../../types/weddingData';
import { builderProjectService } from './builderProjectService';
import { serializeBuilderProject } from '../serializers/projectSerializer';

export type PublishResult = {
  success: boolean;
  publishedAt: string;
  version: number;
  error?: string;
};

export const publishService = {
  async publish(project: BuilderProject): Promise<PublishResult> {
    try {
      const normalizedProject = serializeBuilderProject(project);
      await builderProjectService.saveDraft(normalizedProject);
      const publishMeta = await builderProjectService.publishProject(normalizedProject.id, normalizedProject.weddingId);

      return {
        success: true,
        publishedAt: publishMeta.publishedAt,
        version: publishMeta.version,
      };
    } catch (err) {
      return {
        success: false,
        publishedAt: '',
        version: project.publishedVersion ?? 0,
        error: err instanceof Error ? err.message : 'Unknown publish error',
      };
    }
  },

  async saveDraft(project: BuilderProject, weddingData?: WeddingDataV1): Promise<void> {
    return builderProjectService.saveDraft(project, weddingData);
  },
};

import { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { Select } from '../components/ui/Select';
import { Textarea } from '../components/ui/Textarea';
import { Card } from '../components/ui/Card';
import { LanguageSwitcher } from '../components/ui/LanguageSwitcher';
import { CheckCircle, Search, AlertCircle, User } from 'lucide-react';
import { demoGuests, demoRSVPs } from '../lib/demoData';
import { DEMO_MODE } from '../config/env';

const RSVP_FN_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/validate-rsvp-token`;
const ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY;
const DEMO_RSVP_QUESTIONS_KEY = 'dayof_demo_rsvp_custom_questions_v1';
const DEMO_RSVP_RESPONSES_KEY = 'dayof_demo_rsvp_responses_v1';
const DEMO_RSVP_MEAL_KEY = 'dayof_demo_rsvp_meal_config_v1';

async function rsvpCall(body: object): Promise<{ data?: unknown; error?: string }> {
  const res = await fetch(RSVP_FN_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${ANON_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) return { error: (json as { error?: string })?.error ?? `Error ${res.status}` };
  return { data: json };
}

interface Guest {
  id: string;
  first_name: string | null;
  last_name: string | null;
  name: string;
  email: string | null;
  phone: string | null;
  group_name: string | null;
  wedding_site_id: string;
  plus_one_allowed: boolean;
  invited_to_ceremony: boolean;
  invited_to_reception: boolean;
  invite_token: string | null;
}

interface ExistingRSVP {
  id: string;
  attending: boolean;
  meal_choice: string | null;
  plus_one_name: string | null;
  notes: string | null;
  custom_answers?: Record<string, string | string[]> | null;
}

interface HouseholdGuest {
  id: string;
  first_name: string | null;
  last_name: string | null;
  name: string;
  invite_token: string | null;
}

interface RSVPMealConfig {
  enabled: boolean;
  options: string[];
}

interface RSVPQuestion {
  id: string;
  label: string;
  type: 'short_text' | 'long_text' | 'single_choice' | 'multi_choice';
  required?: boolean;
  options?: string[];
  appliesTo?: 'all' | 'ceremony' | 'reception';
}

function maskEmail(email: string | null): string {
  if (!email) return '';
  const [local, domain] = email.split('@');
  if (!domain) return email;
  const visible = local.length > 2 ? local.slice(0, 2) : local.slice(0, 1);
  return `${visible}***@${domain}`;
}

function guestLabel(g: Guest): string {
  if (g.first_name && g.last_name) return `${g.first_name} ${g.last_name}`;
  return g.name || 'Guest';
}


function parseEventSelectionsFromNotes(notes: string | null, guest: Guest): { cleanNotes: string; attendCeremony: boolean; attendReception: boolean } {
  const fallback = {
    cleanNotes: notes || '',
    attendCeremony: !!guest.invited_to_ceremony,
    attendReception: !!guest.invited_to_reception,
  };

  if (!notes) return fallback;

  const match = notes.match(/\[Events\s+([^\]]+)\]/i);
  if (!match) return fallback;

  const eventPart = match[1] || '';
  const map = Object.fromEntries(
    eventPart
      .split(',')
      .map((piece) => piece.trim())
      .map((piece) => {
        const [k, v] = piece.split(':').map((x) => (x || '').trim().toLowerCase());
        return [k, v === 'yes'];
      })
  ) as Record<string, boolean>;

  const cleanNotes = notes.replace(match[0], '').trim();

  return {
    cleanNotes,
    attendCeremony: guest.invited_to_ceremony ? (map['ceremony'] ?? true) : false,
    attendReception: guest.invited_to_reception ? (map['reception'] ?? true) : false,
  };
}



function getDemoMealConfig(): RSVPMealConfig {
  try {
    const raw = localStorage.getItem(DEMO_RSVP_MEAL_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (!parsed || typeof parsed !== 'object') return { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] };
    return {
      enabled: typeof parsed.enabled === 'boolean' ? parsed.enabled : true,
      options: Array.isArray(parsed.options) ? parsed.options.filter((x: unknown): x is string => typeof x === 'string' && x.trim().length > 0) : ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'],
    };
  } catch {
    return { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] };
  }
}

function getDemoQuestions(): RSVPQuestion[] {
  try {
    const raw = localStorage.getItem(DEMO_RSVP_QUESTIONS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function getDemoStoredResponses(): Record<string, ExistingRSVP> {
  try {
    const raw = localStorage.getItem(DEMO_RSVP_RESPONSES_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return (parsed && typeof parsed === 'object') ? parsed as Record<string, ExistingRSVP> : {};
  } catch {
    return {};
  }
}

function mapDemoGuest(g: (typeof demoGuests)[number]): Guest {
  return {
    id: g.id,
    first_name: g.first_name ?? null,
    last_name: g.last_name ?? null,
    name: g.name,
    email: g.email ?? null,
    phone: null,
    group_name: null,
    wedding_site_id: g.wedding_site_id,
    plus_one_allowed: false,
    invited_to_ceremony: !!g.invited_to_ceremony,
    invited_to_reception: !!g.invited_to_reception,
    invite_token: g.invite_token ?? null,
  };
}

function demoLookup(searchValue: string): { guest: Guest | null; existingRsvp: ExistingRSVP | null; guests: Guest[] | null; rsvpDeadline: string | null; rsvpQuestions: RSVPQuestion[]; rsvpMealConfig: RSVPMealConfig; householdGuests: HouseholdGuest[] } {
  const trimmed = searchValue.trim().toLowerCase();
  const questions = getDemoQuestions();
  const meal = getDemoMealConfig();
  const householdFor = (g: (typeof demoGuests)[number]): HouseholdGuest[] => demoGuests.filter((x) => x.household_id === g.household_id && x.id !== g.id).map((x) => ({ id: x.id, first_name: x.first_name ?? null, last_name: x.last_name ?? null, name: x.name, invite_token: x.invite_token ?? null }));
  const stored = getDemoStoredResponses();

  const tokenMatch = demoGuests.find((g) => (g.invite_token || '').toLowerCase() === trimmed);
  if (tokenMatch) {
    const mapped = mapDemoGuest(tokenMatch);
    const existing = stored[tokenMatch.id] ?? (demoRSVPs.find((r) => r.guest_id === tokenMatch.id)
      ? {
          id: `demo-rsvp-${tokenMatch.id}`,
          attending: !!demoRSVPs.find((r) => r.guest_id === tokenMatch.id)?.attending,
          meal_choice: demoRSVPs.find((r) => r.guest_id === tokenMatch.id)?.meal_choice ?? null,
          plus_one_name: demoRSVPs.find((r) => r.guest_id === tokenMatch.id)?.plus_one_name ?? null,
          notes: demoRSVPs.find((r) => r.guest_id === tokenMatch.id)?.notes ?? null,
          custom_answers: null,
        }
      : null);
    return { guest: mapped, existingRsvp: existing ?? null, guests: null, rsvpDeadline: null, rsvpQuestions: questions, rsvpMealConfig: meal, householdGuests: householdFor(tokenMatch) };
  }

  const matches = demoGuests.filter((g) => g.name.toLowerCase().includes(trimmed) || `${g.first_name ?? ''} ${g.last_name ?? ''}`.trim().toLowerCase().includes(trimmed));
  if (matches.length === 0) return { guest: null, existingRsvp: null, guests: null, rsvpDeadline: null, rsvpQuestions: questions, rsvpMealConfig: meal, householdGuests: [] };
  if (matches.length === 1) {
    const g = matches[0];
    const mapped = mapDemoGuest(g);
    const existing = stored[g.id] ?? (demoRSVPs.find((r) => r.guest_id === g.id)
      ? {
          id: `demo-rsvp-${g.id}`,
          attending: !!demoRSVPs.find((r) => r.guest_id === g.id)?.attending,
          meal_choice: demoRSVPs.find((r) => r.guest_id === g.id)?.meal_choice ?? null,
          plus_one_name: demoRSVPs.find((r) => r.guest_id === g.id)?.plus_one_name ?? null,
          notes: demoRSVPs.find((r) => r.guest_id === g.id)?.notes ?? null,
          custom_answers: null,
        }
      : null);
    return { guest: mapped, existingRsvp: existing ?? null, guests: null, rsvpDeadline: null, rsvpQuestions: questions, rsvpMealConfig: meal, householdGuests: householdFor(g) };
  }

  return { guest: null, existingRsvp: null, guests: matches.slice(0, 10).map(mapDemoGuest), rsvpDeadline: null, rsvpQuestions: questions, rsvpMealConfig: meal, householdGuests: [] };
}

export default function RSVP() {
  const { t } = useTranslation();
  const [searchParams] = useSearchParams();
  const [step, setStep] = useState<'search' | 'pick' | 'form' | 'success'>('search');
  const [searchValue, setSearchValue] = useState('');
  const [guest, setGuest] = useState<Guest | null>(null);
  const [ambiguousGuests, setAmbiguousGuests] = useState<Guest[]>([]);
  const [existingRsvp, setExistingRsvp] = useState<ExistingRSVP | null>(null);
  const [rsvpDeadline, setRsvpDeadline] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [tokenAutoLoading, setTokenAutoLoading] = useState(false);
  const [activePredictionIndex, setActivePredictionIndex] = useState(-1);
  const [formStep, setFormStep] = useState<1 | 2 | 3>(1);
  const [rsvpQuestions, setRsvpQuestions] = useState<RSVPQuestion[]>([]);
  const [customAnswers, setCustomAnswers] = useState<Record<string, string | string[]>>({});
  const [mealConfig, setMealConfig] = useState<RSVPMealConfig>({ enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] });
  const [householdGuests, setHouseholdGuests] = useState<HouseholdGuest[]>([]);
  const [applyToHousehold, setApplyToHousehold] = useState(true);

  const [formData, setFormData] = useState({
    attending: true,
    attendCeremony: true,
    attendReception: true,
    meal_choice: '',
    plus_one_name: '',
    notes: '',
  });

  useEffect(() => {
    const token = searchParams.get('token');
    if (!token) return;
    setTokenAutoLoading(true);
    setSearchValue(token);
    (DEMO_MODE ? Promise.resolve({ data: demoLookup(token) as unknown, error: undefined as string | undefined }) : rsvpCall({ action: 'lookup', searchValue: token }))
      .then(({ data, error: err }) => {
        if (err || !data) {
          setError(err ?? 'Invalid invitation link. Please search by name below.');
          setTokenAutoLoading(false);
          return;
        }
        const result = data as { guest: Guest | null; existingRsvp: ExistingRSVP | null; guests: Guest[] | null; rsvpDeadline: string | null; rsvpQuestions?: RSVPQuestion[] | null; rsvpMealConfig?: RSVPMealConfig | null; householdGuests?: HouseholdGuest[] | null };
        if (result.guest) {
          selectGuest(result.guest, result.existingRsvp, result.rsvpDeadline, result.rsvpQuestions ?? [], result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] }, result.householdGuests ?? []);
        } else if (result.guests && result.guests.length > 1) {
          setAmbiguousGuests(result.guests);
          setRsvpDeadline(result.rsvpDeadline);
          setRsvpQuestions(result.rsvpQuestions ?? []);
        setMealConfig(result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] });
        setHouseholdGuests(result.householdGuests ?? []);
        setApplyToHousehold((result.householdGuests?.length ?? 0) > 0);
          setHouseholdGuests(result.householdGuests ?? []);
          setApplyToHousehold((result.householdGuests?.length ?? 0) > 0);
          setMealConfig(result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] });
          setHouseholdGuests(result.householdGuests ?? []);
          setApplyToHousehold((result.householdGuests?.length ?? 0) > 0);
          setStep('pick');
        } else {
          setError('Invitation not recognized. Please search by name below.');
        }
      })
      .catch(() => setError('Failed to load invitation. Please search by name below.'))
      .finally(() => setTokenAutoLoading(false));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const lookupResp: { data?: unknown; error?: string } = DEMO_MODE
        ? { data: demoLookup(searchValue.trim()) as unknown }
        : await rsvpCall({ action: 'lookup', searchValue: searchValue.trim() });
      const data = lookupResp.data;
      const err = lookupResp.error;
      if (err) {
        setError(err);
        return;
      }

      const result = data as { guest: Guest | null; existingRsvp: ExistingRSVP | null; guests: Guest[] | null; rsvpDeadline: string | null; rsvpQuestions?: RSVPQuestion[] | null; rsvpMealConfig?: RSVPMealConfig | null; householdGuests?: HouseholdGuest[] | null };

      if (result.guests && result.guests.length > 1) {
        setAmbiguousGuests(result.guests);
        setRsvpDeadline(result.rsvpDeadline);
        setRsvpQuestions(result.rsvpQuestions ?? []);
          setMealConfig(result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] });
          setHouseholdGuests(result.householdGuests ?? []);
          setApplyToHousehold((result.householdGuests?.length ?? 0) > 0);
        setStep('pick');
        return;
      }

      const foundGuest = result.guest!;
      selectGuest(foundGuest, result.existingRsvp, result.rsvpDeadline, result.rsvpQuestions ?? [], result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] }, result.householdGuests ?? []);
    } catch {
      setError('An error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const selectGuest = (foundGuest: Guest, foundRsvp: ExistingRSVP | null, deadline: string | null = null, questions: RSVPQuestion[] = [], meal: RSVPMealConfig = { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] }, household: HouseholdGuest[] = []) => {
    setGuest(foundGuest);
    setRsvpDeadline(deadline);
    setRsvpQuestions(questions);
    setMealConfig(meal);
    setHouseholdGuests(household);
    setApplyToHousehold(household.length > 0);
    if (foundRsvp) {
      setExistingRsvp(foundRsvp);
      const parsed = parseEventSelectionsFromNotes(foundRsvp.notes, foundGuest);
      setFormData({
        attending: foundRsvp.attending,
        attendCeremony: parsed.attendCeremony,
        attendReception: parsed.attendReception,
        meal_choice: (() => {
          const current = foundRsvp.meal_choice || '';
          if (!current) return '';
          const match = meal.options.find((opt) => opt.toLowerCase() === current.toLowerCase());
          return match ?? current;
        })(),
        plus_one_name: foundRsvp.plus_one_name || '',
        notes: parsed.cleanNotes,
      });
      setCustomAnswers((foundRsvp.custom_answers && typeof foundRsvp.custom_answers === 'object') ? foundRsvp.custom_answers : {});
    }
    if (!foundRsvp) {
      setFormData(prev => ({
        ...prev,
        attending: true,
        attendCeremony: !!foundGuest.invited_to_ceremony,
        attendReception: !!foundGuest.invited_to_reception,
        meal_choice: '',
        plus_one_name: '',
        notes: '',
      }));
      setCustomAnswers({});
    }
    setFormStep(1);
    setStep('form');
  };

  const handlePickGuest = async (picked: Guest) => {
    setLoading(true);
    setError('');
    try {
      const lookupResp: { data?: unknown; error?: string } = DEMO_MODE
        ? { data: demoLookup(picked.invite_token ?? picked.id) as unknown }
        : await rsvpCall({ action: 'lookup', searchValue: picked.invite_token ?? picked.id });
      const data = lookupResp.data;
      const err = lookupResp.error;
      if (err || !data) {
        selectGuest(picked, null, rsvpDeadline);
        return;
      }
      const result = data as { guest: Guest | null; existingRsvp: ExistingRSVP | null; guests: Guest[] | null; rsvpDeadline: string | null; rsvpQuestions?: RSVPQuestion[] | null; rsvpMealConfig?: RSVPMealConfig | null; householdGuests?: HouseholdGuest[] | null };
      selectGuest(result.guest ?? picked, result.existingRsvp, result.rsvpDeadline, result.rsvpQuestions ?? [], result.rsvpMealConfig ?? { enabled: true, options: ['Chicken', 'Beef', 'Fish', 'Vegetarian', 'Vegan'] }, result.householdGuests ?? []);
    } catch {
      selectGuest(picked, null, rsvpDeadline);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      if (!guest) return;

      if (!guest.invite_token) {
        setError('Your invitation is missing a secure token. Please use the RSVP link from your invitation email.');
        return;
      }

      if (formData.attending && guest.invited_to_ceremony && guest.invited_to_reception && !formData.attendCeremony && !formData.attendReception) {
        setError('Please select at least one event (ceremony or reception), or mark not attending.');
        return;
      }

      const eventSelections: string[] = [];
      if (guest.invited_to_ceremony) eventSelections.push(`Ceremony:${formData.attendCeremony ? 'yes' : 'no'}`);
      if (guest.invited_to_reception) eventSelections.push(`Reception:${formData.attendReception ? 'yes' : 'no'}`);
      const eventTag = eventSelections.length ? `[Events ${eventSelections.join(', ')}]` : '';
      const notesPayload = [formData.notes?.trim() || '', eventTag].filter(Boolean).join('\n').trim();

      if (DEMO_MODE) {
        const stored = getDemoStoredResponses();
        const payload: ExistingRSVP = {
          id: `demo-rsvp-${guest.id}`,
          attending: formData.attending,
          meal_choice: formData.meal_choice || null,
          plus_one_name: formData.plus_one_name || null,
          notes: notesPayload || null,
          custom_answers: customAnswers,
        };
        const targetIds = applyToHousehold ? [guest.id, ...householdGuests.map((h) => h.id)] : [guest.id];
        targetIds.forEach((id) => { stored[id] = { ...payload, id: `demo-rsvp-${id}` }; });
        localStorage.setItem(DEMO_RSVP_RESPONSES_KEY, JSON.stringify(stored));
        setExistingRsvp(payload);
        setStep('success');
        return;
      }

      const { data, error: err } = await rsvpCall({
        action: 'submit',
        guestId: guest.id,
        inviteToken: guest.invite_token,
        attending: formData.attending,
        mealChoice: formData.meal_choice || null,
        plusOneName: formData.plus_one_name || null,
        notes: notesPayload || null,
        customAnswers,
        applyToHousehold,
      });

      if (err) {
        setError(err);
        return;
      }

      setStep('success');
    } catch {
      setError('Failed to submit RSVP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const guestDisplayName = guest
    ? guest.first_name && guest.last_name
      ? `${guest.first_name} ${guest.last_name}`
      : guest.name
    : '';

  const deadlinePassed = rsvpDeadline ? new Date(rsvpDeadline) < new Date() : false;

  const canSubmit = !!guest?.invite_token && !(deadlinePassed && !existingRsvp);


  useEffect(() => {
    setActivePredictionIndex(-1);
  }, [searchValue]);

  const guestPredictions = useMemo(() => {
    if (!DEMO_MODE) return [] as string[];
    const q = searchValue.trim().toLowerCase();
    if (q.length < 2) return [] as string[];
    return demoGuests
      .map((g) => g.name)
      .filter((name, idx, arr) => arr.indexOf(name) === idx)
      .filter((name) => name.toLowerCase().includes(q))
      .slice(0, 6);
  }, [searchValue]);


  const goToNextFormStep = () => {
    if (formStep === 1) {
      if (formData.attending && guest && !guest.invited_to_ceremony && !guest.invited_to_reception) {
        setError('You are marked attending, but no event invitations are enabled for this guest.');
        return;
      }
      setError('');
      setFormStep(2);
      return;
    }

    if (formStep === 2) {
      if (formData.attending && guest?.invited_to_ceremony && guest?.invited_to_reception && !formData.attendCeremony && !formData.attendReception) {
        setError('Please select at least one event before continuing.');
        return;
      }
      if (formData.attending && mealConfig.enabled && !formData.meal_choice) {
        setError('Please choose a meal option before review.');
        return;
      }

      const requiredMissing = rsvpQuestions
        .filter((q) => q.required)
        .filter((q) => (q.appliesTo ?? 'all') === 'all' || ((q.appliesTo === 'ceremony' && formData.attendCeremony) || (q.appliesTo === 'reception' && formData.attendReception)))
        .find((q) => {
          const v = customAnswers[q.id];
          if (Array.isArray(v)) return v.length === 0;
          return !(v || '').toString().trim();
        });

      if (requiredMissing) {
        setError(`Please answer: ${requiredMissing.label}`);
        return;
      }
      setError('');
      setFormStep(3);
    }
  };
  const availableMealValues = useMemo(() => new Set(mealConfig.options.map((o) => o.toLowerCase())), [mealConfig.options]);

  useEffect(() => {
    if (!mealConfig.enabled) {
      if (formData.meal_choice) setFormData((prev) => ({ ...prev, meal_choice: '' }));
      return;
    }
    if (formData.meal_choice && !availableMealValues.has(formData.meal_choice.toLowerCase())) {
      setFormData((prev) => ({ ...prev, meal_choice: '' }));
    }
  }, [mealConfig.enabled, availableMealValues, formData.meal_choice]);

  const invitedEvents = [
    guest?.invited_to_ceremony ? 'Ceremony' : null,
    guest?.invited_to_reception ? 'Reception' : null,
  ].filter(Boolean) as string[];

  if (tokenAutoLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-rose-50 via-white to-amber-50 flex items-center justify-center">
        <div className="text-center space-y-3">
          <div className="w-12 h-12 border-4 border-rose-200 border-t-rose-500 rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 text-sm">Loading your invitation…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-rose-50 via-white to-amber-50">
      <div className="flex justify-end px-6 pt-4">
        <LanguageSwitcher />
      </div>
      <div className="container mx-auto px-4 pb-16 max-w-2xl">
        {step === 'search' && (
          <Card className="p-8">
            <div className="text-center mb-8">
              <h1 className="text-4xl font-serif mb-2">{t('rsvp.title')}</h1>
              <p className="text-gray-600">{t('rsvp.subtitle')}</p>
            </div>

            <form onSubmit={handleSearch} className="space-y-6">
              <div>
                <label className="block text-sm font-medium mb-2">
                  {t('rsvp.search_label')}
                </label>
                <Input
                  type="text"
                  value={searchValue}
                  onChange={(e) => setSearchValue(e.target.value)}
                  onKeyDown={(e) => {
                    if (guestPredictions.length === 0) return;
                    if (e.key === 'ArrowDown') {
                      e.preventDefault();
                      setActivePredictionIndex((idx) => (idx + 1) % guestPredictions.length);
                      return;
                    }
                    if (e.key === 'ArrowUp') {
                      e.preventDefault();
                      setActivePredictionIndex((idx) => (idx <= 0 ? guestPredictions.length - 1 : idx - 1));
                      return;
                    }
                    if (e.key === 'Escape') {
                      e.preventDefault();
                      setActivePredictionIndex(-1);
                      return;
                    }
                    if (e.key === 'Enter' && activePredictionIndex >= 0) {
                      e.preventDefault();
                      setSearchValue(guestPredictions[activePredictionIndex]);
                    }
                  }}
                  placeholder={t('rsvp.search_placeholder')}
                  required
                />
                <p className="text-xs text-gray-500 mt-1.5">
                  Use the invitation code from your email for the fastest lookup
                </p>
                {guestPredictions.length > 0 && (
                  <div className="mt-2 border border-gray-200 rounded-lg bg-white overflow-hidden">
                    {guestPredictions.map((name) => (
                      <button
                        key={name}
                        type="button"
                        onClick={() => setSearchValue(name)}
                        onMouseEnter={() => setActivePredictionIndex(guestPredictions.indexOf(name))}
                        className={`w-full text-left px-3 py-2 text-sm ${guestPredictions[activePredictionIndex] === name ? 'bg-gray-100' : 'hover:bg-gray-50'}`}
                      >
                        {name}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {error && (
                <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm space-y-2">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                    <span>{error}</span>
                  </div>
                  <ul className="pl-6 space-y-1 text-xs text-red-600 list-disc">
                    <li>Make sure you're using the invitation link from your email</li>
                    <li>Try searching by your first and last name</li>
                    <li>Check the spelling matches what the couple has on file</li>
                    <li>Contact the couple if you're still having trouble</li>
                  </ul>
                </div>
              )}

              <Button type="submit" disabled={loading} className="w-full">
                {loading ? 'Searching...' : (
                  <>
                    <Search className="w-4 h-4 mr-2" />
                    Find My Invitation
                  </>
                )}
              </Button>
            </form>
          </Card>
        )}

        {step === 'pick' && (
          <Card className="p-8">
            <div className="text-center mb-6">
              <h1 className="text-2xl font-serif mb-2">Multiple matches found</h1>
              <p className="text-gray-600 text-sm">
                We found {ambiguousGuests.length} guests with that name. Please select yourself below.
              </p>
            </div>

            <div className="space-y-3 mb-6">
              {ambiguousGuests.map((g) => {
                const hints: string[] = [];
                if (g.last_name) hints.push(g.last_name);
                if (g.group_name) hints.push(g.group_name);
                if (g.email) hints.push(maskEmail(g.email));
                if (g.phone) hints.push(`ends in ${g.phone.slice(-4)}`);
                const invitedTo = [
                  g.invited_to_ceremony && 'Ceremony',
                  g.invited_to_reception && 'Reception',
                ].filter(Boolean).join(' + ');
                return (
                  <button
                    key={g.id}
                    onClick={() => handlePickGuest(g)}
                    disabled={loading}
                    className="w-full flex items-center gap-4 p-4 border border-gray-200 rounded-xl hover:border-rose-300 hover:bg-rose-50 transition-colors text-left group"
                  >
                    <div className="w-10 h-10 rounded-full bg-gray-100 group-hover:bg-rose-100 flex items-center justify-center flex-shrink-0 transition-colors">
                      <User className="w-5 h-5 text-gray-500 group-hover:text-rose-500 transition-colors" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-gray-900">{guestLabel(g)}</p>
                      {hints.length > 0 && (
                        <p className="text-sm text-gray-500 truncate">{hints.join(' · ')}</p>
                      )}
                      {invitedTo && (
                        <p className="text-xs text-gray-400 mt-0.5">{invitedTo}</p>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>

            <button
              onClick={() => { setStep('search'); setError(''); setAmbiguousGuests([]); }}
              className="text-sm text-gray-400 hover:text-gray-600 transition-colors"
            >
              Search again
            </button>
          </Card>
        )}

        {step === 'form' && guest && (
          <Card className="p-8">
            <div className="text-center mb-8">
              <h1 className="text-3xl font-serif mb-2">Welcome, {guestDisplayName}!</h1>
              {existingRsvp && (
                <p className="text-sm text-gray-600">
                  You've already responded. You can update your response below.
                </p>
              )}
            </div>

            {deadlinePassed && !existingRsvp && (
              <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-800 text-sm flex items-start gap-2">
                <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                <div>
                  <p className="font-medium">RSVP deadline has passed</p>
                  <p className="mt-0.5">The deadline was {new Date(rsvpDeadline!).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}. Please contact the couple directly.</p>
                </div>
              </div>
            )}

            {deadlinePassed && existingRsvp && (
              <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-sm flex items-start gap-2">
                <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                The RSVP deadline has passed, but you can still update your existing response.
              </div>
            )}

            {!guest.invite_token && (
              <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-sm space-y-1">
                <div className="flex items-start gap-2 font-medium">
                  <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                  Can't submit — missing invitation link
                </div>
                <p className="pl-6">To RSVP, open the invitation email you received and click the RSVP button. That link contains a secure code required to submit your response.</p>
              </div>
            )}

            <div className="mb-6">
              <div className="flex items-center gap-2 text-xs">
                {[1, 2, 3].map((n) => (
                  <div key={n} className={`flex items-center gap-2 ${n < 3 ? 'flex-1' : ''}`}>
                    <div className={`w-6 h-6 rounded-full grid place-items-center font-semibold ${formStep >= n ? 'bg-rose-500 text-white' : 'bg-gray-200 text-gray-500'}`}>{n}</div>
                    {n < 3 && <div className={`h-0.5 flex-1 ${formStep > n ? 'bg-rose-400' : 'bg-gray-200'}`} />}
                  </div>
                ))}
              </div>
              <p className="mt-2 text-xs text-gray-500">{formStep === 1 ? 'Step 1: Attendance' : formStep === 2 ? 'Step 2: Details' : 'Step 3: Final review & submit'} · {Math.round((formStep / 3) * 100)}% complete</p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              {formStep === 1 && (
                <>
                  <div>
                    <label className="block text-sm font-medium mb-2">Will you be attending?</label>
                    <Select
                      value={formData.attending ? 'yes' : 'no'}
                      onChange={(e) => setFormData({ ...formData, attending: e.target.value === 'yes' })}
                      required
                      options={[
                        { value: 'yes', label: "Yes, I'll be there!" },
                        { value: 'no', label: "Sorry, I can't make it" },
                      ]}
                    />
                  </div>

                  {invitedEvents.length > 0 && (
                    <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg text-sm">
                      <p className="font-medium mb-1">You're invited to:</p>
                      <ul className="list-disc list-inside space-y-1 text-gray-700">
                        {invitedEvents.map((ev) => <li key={ev}>{ev}</li>)}
                      </ul>
                    </div>
                  )}
                  {householdGuests.length > 0 && (
                    <label className="flex items-start gap-2 text-sm p-3 bg-amber-50 border border-amber-200 rounded-lg">
                      <input type="checkbox" checked={applyToHousehold} onChange={(e) => setApplyToHousehold(e.target.checked)} className="w-4 h-4 mt-0.5" />
                      <span>
                        Apply this RSVP to household too ({householdGuests.map((h) => h.first_name && h.last_name ? `${h.first_name} ${h.last_name}` : h.name).join(', ')})
                      </span>
                    </label>
                  )}
                </>
              )}

              {formStep === 2 && (
                <>
                  {formData.attending && (
                    <>
                      {(guest.invited_to_ceremony || guest.invited_to_reception) && (
                        <div className="p-4 bg-rose-50 border border-rose-200 rounded-lg space-y-3">
                          <p className="text-sm font-medium text-gray-800">Which events will you attend?</p>
                          {guest.invited_to_ceremony && (
                            <label className="flex items-center justify-between text-sm">
                              <span>Wedding Ceremony</span>
                              <input
                                type="checkbox"
                                checked={formData.attendCeremony}
                                onChange={(e) => setFormData({ ...formData, attendCeremony: e.target.checked })}
                                className="w-4 h-4"
                              />
                            </label>
                          )}
                          {guest.invited_to_reception && (
                            <label className="flex items-center justify-between text-sm">
                              <span>Reception</span>
                              <input
                                type="checkbox"
                                checked={formData.attendReception}
                                onChange={(e) => setFormData({ ...formData, attendReception: e.target.checked })}
                                className="w-4 h-4"
                              />
                            </label>
                          )}
                          <p className="text-xs text-gray-500">Event choices are saved with your RSVP details.</p>
                        </div>
                      )}

                      {mealConfig.enabled && (
                        <div>
                          <label className="block text-sm font-medium mb-2">Meal Choice</label>
                          <Select
                            value={formData.meal_choice}
                            onChange={(e) => setFormData({ ...formData, meal_choice: e.target.value })}
                            options={[
                              { value: '', label: 'Select a meal option' },
                              ...mealConfig.options.map((opt) => ({ value: opt, label: opt })),
                            ]}
                          />
                        </div>
                      )}

                      {guest.plus_one_allowed && (
                        <div>
                          <label className="block text-sm font-medium mb-2">
                            Plus One Name (Optional)
                          </label>
                          <Input
                            type="text"
                            value={formData.plus_one_name}
                            onChange={(e) => setFormData({ ...formData, plus_one_name: e.target.value })}
                            placeholder="Guest's full name"
                          />
                          <p className="text-xs text-gray-500 mt-1">You're welcome to bring a guest</p>
                        </div>
                      )}
                    </>
                  )}


                  {rsvpQuestions.length > 0 && (
                    <div className="space-y-3 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                      <p className="text-sm font-medium text-gray-800">A few quick questions from the couple</p>
                      {rsvpQuestions
                        .filter((q) => (q.appliesTo ?? 'all') === 'all' || ((q.appliesTo === 'ceremony' && formData.attendCeremony) || (q.appliesTo === 'reception' && formData.attendReception)))
                        .map((q) => (
                          <div key={q.id} className="space-y-1">
                            <label className="block text-sm font-medium">{q.label}{q.required ? ' *' : ''}</label>
                            {q.type === 'long_text' ? (
                              <Textarea
                                value={customAnswers[q.id] ?? ''}
                                onChange={(e) => setCustomAnswers((prev) => ({ ...prev, [q.id]: e.target.value }))}
                                rows={3}
                                placeholder="Your answer"
                              />
                            ) : (q.type === 'single_choice' || q.type === 'multi_choice') ? (
                              <div className="space-y-2">
                                {(q.options ?? []).map((opt) => {
                                  const current = customAnswers[q.id];
                                  const checked = q.type === 'multi_choice'
                                    ? (Array.isArray(current) ? current.includes(opt) : false)
                                    : (current ?? '') === opt;
                                  return (
                                    <label key={`${q.id}-${opt}`} className="flex items-center gap-2 text-sm text-gray-800">
                                      <input
                                        type="checkbox"
                                        checked={checked}
                                        onChange={(e) => {
                                          if (q.type === 'multi_choice') {
                                            setCustomAnswers((prev) => {
                                              const curr = Array.isArray(prev[q.id]) ? [...(prev[q.id] as string[])] : [];
                                              if (e.target.checked) {
                                                if (!curr.includes(opt)) curr.push(opt);
                                              } else {
                                                const i = curr.indexOf(opt);
                                                if (i >= 0) curr.splice(i, 1);
                                              }
                                              return { ...prev, [q.id]: curr };
                                            });
                                          } else {
                                            if (e.target.checked) {
                                              setCustomAnswers((prev) => ({ ...prev, [q.id]: opt }));
                                            } else {
                                              setCustomAnswers((prev) => ({ ...prev, [q.id]: '' }));
                                            }
                                          }
                                        }}
                                        className="w-4 h-4"
                                      />
                                      <span>{opt}</span>
                                    </label>
                                  );
                                })}
                              </div>
                            ) : (
                              <Input
                                type="text"
                                value={customAnswers[q.id] ?? ''}
                                onChange={(e) => setCustomAnswers((prev) => ({ ...prev, [q.id]: e.target.value }))}
                                placeholder="Your answer"
                              />
                            )}
                          </div>
                        ))}
                    </div>
                  )}

                  <div>
                    <label className="block text-sm font-medium mb-2">
                      Additional Notes (Optional)
                    </label>
                    <Textarea
                      value={formData.notes}
                      onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                      placeholder="Dietary restrictions, accessibility needs, or special requests"
                      rows={3}
                    />
                  </div>
                </>
              )}

              {formStep === 3 && (
                <div className="bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-3">
                  {formData.attending && guest?.invited_to_ceremony && guest?.invited_to_reception && !formData.attendCeremony && !formData.attendReception && (
                    <div className="text-xs text-warning bg-warning/10 border border-warning/30 rounded-lg px-3 py-2">
                      Please review: attending is on, but no events are selected.
                    </div>
                  )}
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-gray-600 font-medium">Attendance</span>
                    <span className={`font-semibold px-2.5 py-1 rounded-full text-xs ${formData.attending ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {formData.attending ? 'Attending' : 'Not attending'}
                    </span>
                  </div>
                  {formData.attending && (guest.invited_to_ceremony || guest.invited_to_reception) && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-600 font-medium">Events</span>
                      <span className="text-gray-900">{[guest.invited_to_ceremony ? (formData.attendCeremony ? 'Ceremony' : null) : null, guest.invited_to_reception ? (formData.attendReception ? 'Reception' : null) : null].filter(Boolean).join(' + ') || 'None selected'}</span>
                    </div>
                  )}
                  {formData.attending && formData.meal_choice && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-600 font-medium">Meal</span>
                      <span className="text-gray-900 capitalize">{formData.meal_choice}</span>
                    </div>
                  )}
                  {formData.attending && formData.plus_one_name && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-600 font-medium">Plus one</span>
                      <span className="text-gray-900">{formData.plus_one_name}</span>
                    </div>
                  )}

                  {rsvpQuestions.length > 0 && Object.keys(customAnswers).length > 0 && (
                    <div className="space-y-2">
                      <p className="text-xs uppercase tracking-wide text-gray-500">Custom answers</p>
                      {rsvpQuestions.filter((q) => { const v = customAnswers[q.id]; return Array.isArray(v) ? v.length > 0 : String(v ?? '').trim().length > 0; }).map((q) => (
                        <div key={q.id} className="flex items-start justify-between text-sm gap-4">
                          <span className="text-gray-600 font-medium flex-shrink-0">{q.label}</span>
                          <span className="text-gray-900 text-right">{Array.isArray(customAnswers[q.id]) ? (customAnswers[q.id] as string[]).join(', ') : String(customAnswers[q.id] ?? '')}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  {rsvpQuestions.length > 0 && Object.keys(customAnswers).length > 0 && (
                    <div className="space-y-2">
                      <p className="text-xs uppercase tracking-wide text-gray-500">Custom answers</p>
                      {rsvpQuestions.filter((q) => { const v = customAnswers[q.id]; return Array.isArray(v) ? v.length > 0 : String(v ?? '').trim().length > 0; }).map((q) => (
                        <div key={q.id} className="flex items-start justify-between text-sm gap-4">
                          <span className="text-gray-600 font-medium flex-shrink-0">{q.label}</span>
                          <span className="text-gray-900 text-right">{Array.isArray(customAnswers[q.id]) ? (customAnswers[q.id] as string[]).join(', ') : String(customAnswers[q.id] ?? '')}</span>
                        </div>
                      ))}
                    </div>
                  )}
              {formData.notes && (
                    <div className="flex items-start justify-between text-sm gap-4">
                      <span className="text-gray-600 font-medium flex-shrink-0">Notes</span>
                      <span className="text-gray-900 text-right">{formData.notes}</span>
                    </div>
                  )}
                </div>
              )}

              {error && (
                <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm flex items-start gap-2">
                  <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                  {error}
                </div>
              )}

              <div className="flex gap-4">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    if (formStep > 1) {
                      setFormStep((formStep - 1) as 1 | 2 | 3);
                    } else {
                      setStep('search');
                      setError('');
                    }
                  }}
                  className="flex-1"
                >
                  {formStep > 1 ? 'Back' : 'Cancel'}
                </Button>

                {formStep < 3 ? (
                  <Button
                    type="button"
                    onClick={goToNextFormStep}
                    className="flex-1"
                  >
                    {formStep === 1 ? 'Continue to details' : 'Continue to review'}
                  </Button>
                ) : (
                  <Button
                    type="submit"
                    disabled={loading || !canSubmit}
                    className="flex-1"
                  >
                    {loading ? 'Submitting...' : existingRsvp ? 'Update RSVP' : 'Submit RSVP'}
                  </Button>
                )}
              </div>
            </form>
          </Card>
        )}

        {step === 'success' && (
          <Card className="p-8">
            <div className="text-center mb-6">
              <div className="flex justify-center mb-4">
                <div className={`w-16 h-16 rounded-full flex items-center justify-center ${formData.attending ? 'bg-green-100' : 'bg-neutral-100'}`}>
                  <CheckCircle className={`w-9 h-9 ${formData.attending ? 'text-green-500' : 'text-neutral-500'}`} />
                </div>
              </div>
              <h1 className="text-3xl font-serif mb-2">
                {formData.attending ? "You're confirmed!" : "Response recorded"}
              </h1>
              <p className="text-gray-500 text-sm">
                {guestDisplayName && `For ${guestDisplayName}`}
              </p>
            </div>

            <div className="bg-gray-50 border border-gray-200 rounded-xl p-5 mb-6 space-y-3">
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600 font-medium">Attendance</span>
                <span className={`font-semibold px-2.5 py-1 rounded-full text-xs ${
                  formData.attending
                    ? 'bg-green-100 text-green-700'
                    : 'bg-red-100 text-red-700'
                }`}>
                  {formData.attending ? "Attending" : "Not attending"}
                </span>
              </div>
              {formData.attending && formData.meal_choice && (
                <div className="flex items-center justify-between text-sm">
                  <span className="text-gray-600 font-medium">Meal</span>
                  <span className="text-gray-900 capitalize">{formData.meal_choice}</span>
                </div>
              )}
              {formData.attending && formData.plus_one_name && (
                <div className="flex items-center justify-between text-sm">
                  <span className="text-gray-600 font-medium">Plus one</span>
                  <span className="text-gray-900">{formData.plus_one_name}</span>
                </div>
              )}
              {formData.notes && (
                <div className="flex items-start justify-between text-sm gap-4">
                  <span className="text-gray-600 font-medium flex-shrink-0">Notes</span>
                  <span className="text-gray-900 text-right">{formData.notes}</span>
                </div>
              )}
            </div>

            {formData.attending && (
              <p className="text-center text-sm text-green-700 bg-green-50 border border-green-200 rounded-lg py-3 px-4 mb-6">
                We can't wait to celebrate with you!
              </p>
            )}
            {!formData.attending && (
              <p className="text-center text-sm text-gray-600 bg-gray-50 border border-gray-200 rounded-lg py-3 px-4 mb-6">
                We'll miss you, but thank you for letting us know.
              </p>
            )}

            <Button
              variant="outline"
              onClick={() => {
                setStep('search');
                setSearchValue('');
                setGuest(null);

                setExistingRsvp(null);
                setAmbiguousGuests([]);
                setRsvpDeadline(null);
                setFormData({ attending: true, attendCeremony: true, attendReception: true, meal_choice: '', plus_one_name: '', notes: '' });
                setCustomAnswers({});
                setRsvpQuestions([]);
                setFormStep(1);
              }}
              className="w-full"
            >
              Submit Another RSVP
            </Button>
          </Card>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Calendar, Clock, MapPin, Check, X, ExternalLink, AlertCircle, Loader2 } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Button } from '../components/ui/Button';
import { Card } from '../components/ui/Card';
import { Input } from '../components/ui/Input';
import { Textarea } from '../components/ui/Textarea';
import { Header, Footer } from '../components/layout';

interface Guest {
  id: string;
  name: string;
  email: string;
}

interface ItineraryEvent {
  id: string;
  event_name: string;
  description: string;
  event_date: string;
  start_time: string;
  end_time: string | null;
  location_name: string;
  location_address: string;
  dress_code: string | null;
  notes: string | null;
}

interface EventInvitation {
  id: string;
  event_id: string;
  event: ItineraryEvent;
  rsvp?: {
    attending: boolean;
    dietary_restrictions: string | null;
    notes: string | null;
  };
}

export default function EventRSVP() {
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');

  const [guest, setGuest] = useState<Guest | null>(null);
  const [invitations, setInvitations] = useState<EventInvitation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedEvent, setSelectedEvent] = useState<string | null>(null);
  const [rsvpForm, setRsvpForm] = useState({
    attending: true,
    dietary_restrictions: '',
    notes: '',
  });
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [submitSuccess, setSubmitSuccess] = useState(false);

  useEffect(() => {
    if (token) {
      loadGuestAndEvents();
    } else {
      setError('No invitation link found. Please use the link from your invitation email.');
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  async function loadGuestAndEvents() {
    try {
      const { data: guestData, error: guestError } = await supabase
        .from('guests')
        .select('id, name, email')
        .eq('invite_token', token)
        .maybeSingle();

      if (guestError) throw guestError;
      if (!guestData) {
        setError("This invitation link isn't valid. Please use the link from your invitation email, or ask the couple for a new one.");
        setLoading(false);
        return;
      }

      setGuest(guestData);

      const { data: invitationsData, error: invitationsError } = await supabase
        .from('event_invitations')
        .select(`
          id,
          event_id,
          itinerary_events (
            id,
            event_name,
            description,
            event_date,
            start_time,
            end_time,
            location_name,
            location_address,
            dress_code,
            notes
          )
        `)
        .eq('guest_id', guestData.id);

      if (invitationsError) throw invitationsError;

      const invitationsWithRsvps = await Promise.all(
        (invitationsData || []).map(async (invitation) => {
          const { data: rsvpData } = await supabase
            .from('event_rsvps')
            .select('attending, dietary_restrictions, notes')
            .eq('event_invitation_id', invitation.id)
            .maybeSingle();

          return {
            id: invitation.id,
            event_id: invitation.event_id,
            event: invitation.itinerary_events as unknown as ItineraryEvent,
            rsvp: rsvpData || undefined,
          };
        })
      );

      setInvitations(invitationsWithRsvps);
    } catch {
      setError('Failed to load your event invitations. Please try again or contact the couple.');
    } finally {
      setLoading(false);
    }
  }

  function formatDate(dateString: string) {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
      year: 'numeric',
    });
  }

  function formatTime(timeString: string | null) {
    if (!timeString) return '';
    const [hours, minutes] = timeString.split(':');
    const hour = parseInt(hours);
    const ampm = hour >= 12 ? 'PM' : 'AM';
    const displayHour = hour % 12 || 12;
    return `${displayHour}:${minutes} ${ampm}`;
  }

  function getMapUrl(locationName: string, locationAddress: string) {
    const query = encodeURIComponent(`${locationName} ${locationAddress}`.trim());
    return `https://www.google.com/maps/search/?api=1&query=${query}`;
  }

  function openRsvpForm(invitation: EventInvitation) {
    setSelectedEvent(invitation.id);
    setSubmitError('');
    setSubmitSuccess(false);
    if (invitation.rsvp) {
      setRsvpForm({
        attending: invitation.rsvp.attending,
        dietary_restrictions: invitation.rsvp.dietary_restrictions || '',
        notes: invitation.rsvp.notes || '',
      });
    } else {
      setRsvpForm({
        attending: true,
        dietary_restrictions: '',
        notes: '',
      });
    }
  }

  async function handleSubmitRsvp(e: React.FormEvent) {
    e.preventDefault();
    if (!selectedEvent || submitting) return;

    setSubmitting(true);
    setSubmitError('');

    try {
      const invitation = invitations.find((i) => i.id === selectedEvent);
      if (!invitation) return;

      if (invitation.rsvp) {
        const { error } = await supabase
          .from('event_rsvps')
          .update({
            attending: rsvpForm.attending,
            dietary_restrictions: rsvpForm.dietary_restrictions || null,
            notes: rsvpForm.notes || null,
            responded_at: new Date().toISOString(),
          })
          .eq('event_invitation_id', selectedEvent);

        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('event_rsvps')
          .insert([
            {
              event_invitation_id: selectedEvent,
              attending: rsvpForm.attending,
              dietary_restrictions: rsvpForm.dietary_restrictions || null,
              notes: rsvpForm.notes || null,
            },
          ]);

        if (error) throw error;
      }

      setSubmitSuccess(true);
      setTimeout(() => {
        setSelectedEvent(null);
        setSubmitSuccess(false);
        loadGuestAndEvents();
      }, 2000);
    } catch {
      setSubmitError('Failed to save your RSVP. Please try again.');
    } finally {
      setSubmitting(false);
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="flex items-center justify-center py-20">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
        </div>
        <Footer />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="max-w-2xl mx-auto px-4 py-20 text-center">
          <div className="w-16 h-16 rounded-full bg-red-100 flex items-center justify-center mx-auto mb-6">
            <AlertCircle className="w-8 h-8 text-red-500" />
          </div>
          <h1 className="text-2xl font-bold text-neutral-900 mb-3">Link Not Recognized</h1>
          <p className="text-neutral-600 max-w-md mx-auto">{error}</p>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-4xl mx-auto px-4 py-12">
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold text-neutral-900 mb-3">
            Hello, {guest?.name}!
          </h1>
          <p className="text-lg text-neutral-600">
            {invitations.length === 1
              ? "You're invited to the event below. Please let us know if you can make it."
              : `You're invited to ${invitations.length} events. Please RSVP for each one.`}
          </p>
        </div>

        {invitations.length === 0 ? (
          <Card className="p-12 text-center">
            <Calendar className="w-12 h-12 text-neutral-400 mx-auto mb-4" />
            <p className="text-neutral-600">
              No additional events found for your invitation.
            </p>
          </Card>
        ) : (
          <div className="space-y-6">
            {invitations.map((invitation) => (
              <Card key={invitation.id} className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-3 flex-wrap">
                      <h2 className="text-2xl font-semibold text-neutral-900">
                        {invitation.event.event_name}
                      </h2>
                      {invitation.rsvp && (
                        <span
                          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium ${
                            invitation.rsvp.attending
                              ? 'bg-green-100 text-green-700'
                              : 'bg-neutral-100 text-neutral-600'
                          }`}
                        >
                          {invitation.rsvp.attending
                            ? <><Check className="w-3.5 h-3.5" /> Attending</>
                            : <><X className="w-3.5 h-3.5" /> Not attending</>
                          }
                        </span>
                      )}
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center text-neutral-600">
                        <Calendar className="w-5 h-5 mr-2 flex-shrink-0" />
                        <span>{formatDate(invitation.event.event_date)}</span>
                      </div>

                      {invitation.event.start_time && (
                        <div className="flex items-center text-neutral-600">
                          <Clock className="w-5 h-5 mr-2 flex-shrink-0" />
                          <span>
                            {formatTime(invitation.event.start_time)}
                            {invitation.event.end_time &&
                              ` – ${formatTime(invitation.event.end_time)}`}
                          </span>
                        </div>
                      )}

                      {invitation.event.location_name && (
                        <div className="flex items-center gap-3 text-neutral-600">
                          <MapPin className="w-5 h-5 flex-shrink-0" />
                          <div className="flex-1">
                            <div>{invitation.event.location_name}</div>
                            {invitation.event.location_address && (
                              <div className="text-sm text-neutral-500">
                                {invitation.event.location_address}
                              </div>
                            )}
                          </div>
                          <a
                            href={getMapUrl(invitation.event.location_name || '', invitation.event.location_address || '')}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-1 px-3 py-2 text-sm bg-primary-50 text-primary-700 hover:bg-primary-100 rounded-lg transition-colors whitespace-nowrap"
                          >
                            <MapPin className="w-4 h-4" />
                            View Map
                            <ExternalLink className="w-3 h-3" />
                          </a>
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {invitation.event.description && (
                  <p className="text-neutral-600 mb-4">{invitation.event.description}</p>
                )}

                {invitation.event.dress_code && (
                  <div className="mb-4 text-sm">
                    <span className="font-medium text-neutral-700">Dress Code:</span>{' '}
                    <span className="text-neutral-600">{invitation.event.dress_code}</span>
                  </div>
                )}

                {invitation.event.notes && (
                  <div className="mb-4 p-3 bg-neutral-50 rounded-lg text-sm text-neutral-600">
                    {invitation.event.notes}
                  </div>
                )}

                <Button
                  onClick={() => openRsvpForm(invitation)}
                  className="w-full mt-2"
                  variant={invitation.rsvp ? 'outline' : 'primary'}
                >
                  {invitation.rsvp ? 'Update my RSVP' : 'RSVP for this event'}
                </Button>
              </Card>
            ))}
          </div>
        )}
      </main>

      {selectedEvent && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <Card className="w-full max-w-lg">
            {submitSuccess ? (
              <div className="p-8 text-center">
                <div className="w-16 h-16 rounded-full bg-green-100 flex items-center justify-center mx-auto mb-4">
                  <Check className="w-9 h-9 text-green-600" />
                </div>
                <h3 className="text-2xl font-bold text-neutral-900 mb-2">
                  {rsvpForm.attending ? "You're in!" : "Response saved"}
                </h3>
                <p className="text-neutral-500 text-sm">
                  {rsvpForm.attending
                    ? `Looking forward to seeing you at ${invitations.find(i => i.id === selectedEvent)?.event.event_name}!`
                    : "Thank you for letting us know."}
                </p>
              </div>
            ) : (
              <>
                <div className="p-6 border-b border-neutral-200">
                  <h3 className="text-xl font-semibold text-neutral-900">
                    {invitations.find((i) => i.id === selectedEvent)?.event.event_name}
                  </h3>
                  <p className="text-sm text-neutral-500 mt-1">
                    {(() => {
                      const inv = invitations.find(i => i.id === selectedEvent);
                      return inv ? formatDate(inv.event.event_date) : '';
                    })()}
                  </p>
                </div>

                <form onSubmit={handleSubmitRsvp} className="p-6 space-y-5">
                  <div>
                    <label className="block text-sm font-medium text-neutral-700 mb-3">
                      Will you attend?
                    </label>
                    <div className="grid grid-cols-2 gap-3">
                      <button
                        type="button"
                        onClick={() => setRsvpForm({ ...rsvpForm, attending: true })}
                        className={`flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-medium transition-all ${
                          rsvpForm.attending
                            ? 'bg-green-600 text-white shadow-sm'
                            : 'bg-neutral-100 text-neutral-600 hover:bg-neutral-200'
                        }`}
                      >
                        <Check className="w-4 h-4" />
                        Yes, I'll be there
                      </button>
                      <button
                        type="button"
                        onClick={() => setRsvpForm({ ...rsvpForm, attending: false })}
                        className={`flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-medium transition-all ${
                          !rsvpForm.attending
                            ? 'bg-neutral-700 text-white shadow-sm'
                            : 'bg-neutral-100 text-neutral-600 hover:bg-neutral-200'
                        }`}
                      >
                        <X className="w-4 h-4" />
                        Can't make it
                      </button>
                    </div>
                  </div>

                  {rsvpForm.attending && (
                    <>
                      <div>
                        <label className="block text-sm font-medium text-neutral-700 mb-1">
                          Dietary restrictions <span className="text-neutral-400 font-normal">(optional)</span>
                        </label>
                        <Input
                          value={rsvpForm.dietary_restrictions}
                          onChange={(e) =>
                            setRsvpForm({ ...rsvpForm, dietary_restrictions: e.target.value })
                          }
                          placeholder="e.g., Vegetarian, Gluten-free, Nut allergy"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-neutral-700 mb-1">
                          Additional notes <span className="text-neutral-400 font-normal">(optional)</span>
                        </label>
                        <Textarea
                          value={rsvpForm.notes}
                          onChange={(e) => setRsvpForm({ ...rsvpForm, notes: e.target.value })}
                          placeholder="Any special requests or messages for the couple"
                          rows={3}
                        />
                      </div>
                    </>
                  )}

                  {submitError && (
                    <div className="flex items-start gap-2 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
                      <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
                      {submitError}
                    </div>
                  )}

                  <div className="flex gap-3 pt-1">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        if (!submitting) setSelectedEvent(null);
                      }}
                      className="flex-1"
                      disabled={submitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      disabled={submitting}
                      className="flex-1"
                    >
                      {submitting
                        ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Saving…</>
                        : invitations.find(i => i.id === selectedEvent)?.rsvp
                          ? 'Update RSVP'
                          : 'Submit RSVP'
                      }
                    </Button>
                  </div>
                </form>
              </>
            )}
          </Card>
        </div>
      )}

      <Footer />
    </div>
  );
}

