  if (insSug.error) throw insSug.error;

  const selVotes = await supabase.from('interactive_votes').select('option_id').eq('site_slug', siteSlug).eq('widget_id', 'poll-test');
  if (selVotes.error) throw selVotes.error;
  const selSugs = await supabase.from('interactive_suggestions').select('suggestion_text').eq('site_slug', siteSlug).eq('prompt_key', 'ideas');
