  const endpoint = 'https://atuzuobpprjstfmdnwso.supabase.co/functions/v1/registry-preview';
  const apikey = (window.__ENV && window.__ENV.VITE_SUPABASE_ANON_KEY) || localStorage.getItem('sb-anon-key') || '';
  const urls = [
    'https://www.amazon.com/dp/B07FZ8S74R',
    'https://www.target.com/p/keurig-k-mini-single-serve-k-cup-pod-coffee-maker/-/A-53135850',
    'https://www.etsy.com/listing/1162354150/personalized-cutting-board',
    'https://www.walmart.com/ip/Instant-Pot-Duo-7-in-1-Electric-Pressure-Cooker-6-Quart/45918917',
    'https://www.wayfair.com/furniture/pdp/ebern-designs-upholstered-dining-chair-w004846577.html',
    'https://www.crateandbarrel.com/marin-white-dinner-plate/s608843',
    'https://www.williams-sonoma.com/products/all-clad-d5-stainless-steel-fry-pan/',
    'https://www.potterybarn.com/products/sausalito-dinnerware-set/',
    'https://www.ikea.com/us/en/p/kallax-shelf-unit-white-80275887/',
    'https://www.bestbuy.com/site/apple-airpods-pro-2nd-generation-with-magsafe-case-usb-c-white/6447382.p',
    'https://www.anthropologie.com/shop/gleaming-primrose-mirror2',
    'https://www.macys.com/shop/product/ninja-foodi-power-blender'
  ];
  const out = [];
  for (const url of urls) {
    try {
      const resp = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'apikey': apikey },
        body: JSON.stringify({ url })
      });
      const j = await resp.json();
      out.push({
        site: new URL(url).hostname.replace('www.',''),
        status: resp.status,
        titleOk: !!(j.title && j.title.trim().length > 2),
        imageOk: !!(j.image_url && /^https?:\/\//.test(j.image_url)),
        priceOk: !!j.price_label,
        partial: !!j.partial,
        missing: j.missing_fields || [],
        title: (j.title || '').slice(0,70)
      });
    } catch (e) {
      out.push({ site: new URL(url).hostname.replace('www.',''), error: String(e) });
    }
  }
  const summary = {
    tested: out.length,
    titleOk: out.filter(r => r.titleOk).length,
    imageOk: out.filter(r => r.imageOk).length,
    priceOk: out.filter(r => r.priceOk).length,
    fullTitleImage: out.filter(r => r.titleOk && r.imageOk).length,
  };
  return { summary, out };
}

