async () => {
  const s=window.__regTest; const endpoint='https://atuzuobpprjstfmdnwso.supabase.co/functions/v1/registry-preview';
  const retrySites=s.results.filter(x=>x.status!==200).map(x=>x.site);
  const siteToUrl = Object.fromEntries(s.urls.map(u=>[new URL(u).hostname.replace('www.',''),u]));
  const retried=[];
  for(const site of retrySites){
    const url=siteToUrl[site]; if(!url) continue;
    const ctrl=new AbortController(); const t=setTimeout(()=>ctrl.abort(),8000);
    try{
      const resp=await fetch(endpoint,{method:'POST',signal:ctrl.signal,headers:{'Content-Type':'application/json','apikey':s.anon,...(s.token?{Authorization:`Bearer ${s.token}`}:{})},body:JSON.stringify({url})});
      const j=await resp.json().catch(()=>({}));
      retried.push({site,status:resp.status,titleOk:!!(j.title&&j.title.trim().length>2),imageOk:!!(j.image_url&&/^https?:\/\//.test(j.image_url)),priceOk:!!j.price_label});
      const idx=s.results.findIndex(r=>r.site===site);
      if(idx>=0) s.results[idx]={...s.results[idx],...retried[retried.length-1]};
    }catch(e){retried.push({site,status:0,error:String(e)})}
    finally{clearTimeout(t)}
  }
  return retried;
}

