const handleBulkUrlImport = async () => {
  const urls = bulkUrlsInput
    .split(/\r?\n|,/)
    .map((s) => s.trim())
    .filter(Boolean)
    .slice(0, 20);

  if (urls.length === 0) return;

  setBulkImporting(true);
  setBulkImportSummary(null);

  let added = 0;
  let failed = 0;

  for (const url of urls) {
    try {
      const preview = await fetchUrlPreview(url);
      const payload = {
        item_name: preview.title || 'Registry item',
        item_url: preview.canonical_url || url,
        image_url: preview.image_url || null,
        merchant: preview.store_name || null,
        price_label: preview.price_label || null,
        price_amount: preview.price_amount ?? null,
        notes: preview.description || null,
        item_type: 'gift' as const,
        item_priority: 0,
        purchase_status: 'available' as const,
        hide_when_purchased: false,
        sort_order: items.length + added,
      };
      await createRegistryItem(weddingSiteId, payload);
      added += 1;
    } catch (e) {
      failed += 1;
    }
  }

  await loadItems();
  setBulkImporting(false);
  setBulkImportSummary(`Added ${added} item${added === 1 ? '' : 's'}${failed ? `, ${failed} failed` : ''}.`);
  if (added > 0) setBulkUrlsInput('');
};

